```sql
/* Вычисляем процент канцерогенных молекул, содержащих элемент Chlorine (cl) */
SELECT
    /* Доля молекул с label = '+' и содержащих атом cl среди всех молекул */
    COUNT(DISTINCT CASE WHEN m."label" = '+' AND a."element" = 'cl' THEN m."molecule_id" END)::NUMERIC
    / NULLIF(COUNT(DISTINCT m."molecule_id"), 0) AS percentage
FROM "molecule" m
LEFT JOIN "atom" a ON a."molecule_id" = m."molecule_id";
```

